import heapq

def heap_queue_largest(nums, n):
    result = nlargest(n, nums)
    return result

def nlargest(n, nums):
    heap = []
    for num in nums:
        if len(heap) < n:
            heapq.heappush(heap, num)
        elif num > heap[0]:
            heapq.heappop(heap)
            heapq.heappush(heap, num)
    result = []
    while heap:
        largest = heapq.heappop(heap)
        result.insert(0, largest)
    return result

