def amicable_numbers_sum(n):
    def sum_of_divisors(num):
        total = 1
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                total += i
                if i != num // i:
                    total += num // i
        return total

    amicable = set()
    for i in range(2, n + 1):
        if i not in amicable:
            sum_i = sum_of_divisors(i)
            if sum_i != i and sum_i <= n:
                sum_sum_i = sum_of_divisors(sum_i)
                if sum_sum_i == i:
                    amicable.add(i)
                    amicable.add(sum_i)

    return sum(amicable)

