def pancake_sort(arr):
    def flip(arr, k):
        left, right = 0, k
        while left < right:
            arr[left], arr[right] = arr[right], arr[left]
            left += 1
            right -= 1

    n = len(arr)
    result = arr[:]
    for curr_size in range(n, 1, -1):
        max_idx = 0
        for i in range(1, curr_size):
            if result[i] > result[max_idx]:
                max_idx = i

        if max_idx != curr_size - 1:
            if max_idx != 0:
                flip(result, max_idx)
            flip(result, curr_size - 1)

    return result

