def is_majority(arr, n, target):
    left = 0
    right = n - 1

    # Find the leftmost occurrence of target
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    leftmost = left

    # If target is not found, return False
    if leftmost >= n or arr[leftmost] != target:
        return False

    # Find the rightmost occurrence of target
    right = n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] <= target:
            left = mid + 1
        else:
            right = mid - 1

    rightmost = right

    # Check if the count of target is more than n/2
    count = rightmost - leftmost + 1
    return count > n // 2

