import math
from functools import lru_cache

def count_binary_seq(n):
    @lru_cache(maxsize=None)
    def dp(pos, diff, count):
        if pos == 2 * n:
            return 1 if diff == 0 else 0
        if abs(diff) > 2 * n - pos:
            return 0

        result = 0
        # Place 0 at current position
        result += dp(pos + 1, diff, count + 1)
        # Place 1 at current position
        result += dp(pos + 1, diff + 1 if pos < n else diff - 1, count + 1)

        return result

    return dp(0, 0, 0)

