def convert_list_dictionary(list1, list2, list3):
    result = []
    for k1 in list1:
        index = list1.index(k1)
        k2 = list2[index]
        k3 = list3[index]
        nested_dict = {}
        nested_dict[k2] = k3
        outer_dict = {}
        outer_dict[k1] = nested_dict
        result.append(outer_dict)
    return result

