cycles.task_1_output:
def max_product(arr):
    if not arr:
        return 0

    n = len(arr)
    # dp[i] represents the maximum product of an increasing subsequence ending at index i
    dp = [1] * n

    for i in range(n):
        dp[i] = arr[i]  # At least the element itself
        for j in range(i):
            if arr[j] < arr[i]:
                dp[i] = max(dp[i], dp[j] * arr[i])

    return max(dp)

